cypress_script:
describe('Alerts Page Tests', () => {
  it('should trigger alert dialog', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#alertButton').click();
    cy.on('window:alert', (str) => {
      expect(str).to.eq('You clicked a button');
    });
  });

  it('should trigger confirm dialog and cancel', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#confirmButton').click();
    cy.on('window:confirm', () => false);
    cy.url().should('eq', 'https://demoqa.com/alerts');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Alerts Page Tests', () => {
  test('should trigger alert dialog', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    page.on('dialog', dialog => {
      expect(dialog.message()).toBe('You clicked a button');
      dialog.accept();
    });
    await page.click('#alertButton');
  });

  test('should trigger confirm dialog and cancel', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    page.on('dialog', dialog => {
      expect(dialog.type()).toBe('confirm');
      dialog.dismiss();
    });
    await page.click('#confirmButton');
    await expect(page).toHaveURL('https://demoqa.com/alerts');
  });
});
